    function switchSettingsTab(tabName) {
      const tabs = ['general', 'optimization', 'themes', 'clock'];
      tabs.forEach(function(t) {
        const panel = document.getElementById(`settings-panel-${t}`);
        const btn = document.getElementById(`sett-tab-btn-${t}`);
        if (t === tabName) {
          if (panel) panel.classList.remove('hidden');
          if (btn) {
            btn.classList.remove('text-gray-400');
            btn.classList.add('text-white');
          }
        } else {
          if (panel) panel.classList.add('hidden');
          if (btn) {
            btn.classList.remove('text-white');
            btn.classList.add('text-gray-400');
          }
        }
      });
    }

    function toggleSettingOption(optKey) {
      if (optKey === 'ramOpt') {
        const ramCheckbox = document.getElementById('toggle-ram-opt');
        settingsState.ramOpt = ramCheckbox ? ramCheckbox.checked : !settingsState.ramOpt;
        localStorage.setItem('stash_ram_opt', settingsState.ramOpt);
      } else if (optKey === 'ultOpt') {
        const ultCheckbox = document.getElementById('toggle-ult-opt');
        settingsState.ultOpt = ultCheckbox ? ultCheckbox.checked : !settingsState.ultOpt;
        localStorage.setItem('stash_ult_opt', settingsState.ultOpt);
      }
    }

    function setSiteTheme(themeKey, save = true) {
      if (!themesMap[themeKey]) themeKey = 'default';
      settingsState.theme = themeKey;
      if (save) localStorage.setItem('stash_theme', themeKey);
      const t = themesMap[themeKey], root = document.documentElement;
      root.style.setProperty('--bg-color', t.bg); root.style.setProperty('--ui-bg', t.bg); root.style.setProperty('--ui-bg-2', t.bg2);
      root.style.setProperty('--ui-panel', t.panel); root.style.setProperty('--ui-panel-2', t.panel2); root.style.setProperty('--ui-text', t.text);
      root.style.setProperty('--ui-muted', t.muted); root.style.setProperty('--ui-accent', t.accent); root.style.setProperty('--ui-accent-2', t.accent2);
      document.body.style.backgroundColor=t.bg;
      document.querySelectorAll('.theme-circle').forEach(el=>el.classList.remove('active-theme'));
      const active=document.getElementById('theme-circle-'+themeKey); if(active) active.classList.add('active-theme');
      document.querySelectorAll('[data-settings-theme]').forEach(el=>el.classList.toggle('active',el.getAttribute('data-settings-theme')===themeKey));
      document.querySelectorAll('[data-quick-theme]').forEach(el=>el.classList.toggle('active',el.getAttribute('data-quick-theme')===themeKey));
      const label=document.getElementById('current-theme-label'); if(label) label.textContent=themeKey.charAt(0).toUpperCase()+themeKey.slice(1)+' theme';
    }
