    function handleHashRouter() {
      const hash = window.location.hash.replace('#', '') || 'home';
      
      if (hash.startsWith('app/')) {
        const appId = hash.split('/')[1];
        openAppDetails(appId, false);
      } else if (hash.startsWith('play/')) {
        const appId = hash.split('/')[1];
        const app = storeApps.find(function(a) { return String(a.id) === String(appId); });
        if (app) {
          currentDetailedApp = app;
          launchAppPlayer(false);
        } else {
          showView('home-page-view');
        }
      } else if (hash.startsWith('category/')) {
        const categoryName = decodeURIComponent(hash.split('/')[1]);
        setCategory(categoryName, null, false);
      } else if (hash.startsWith('search/')) {
        const query = decodeURIComponent(hash.split('/')[1]);
        executeSearch(query, false);
      } else if (hash === 'settings') {
        showView('settings-page-view');
      } else if (hash === 'games') {
        openGameVault();
      } else {
        showView('home-page-view');
      }
    }

