    function renderServingHotNow() {
      const grid = document.getElementById('serving-hot-grid');
      if (!grid) return;
      if (storeApps.length === 0) {
        grid.innerHTML = '<p class="text-xs text-gray-500 col-span-full py-4 text-center">No apps currently available.</p>';
        return;
      }
      const top7 = [...storeApps].sort(function(a, b) { return (b.downloads || 0) - (a.downloads || 0); }).slice(0, 7);
      grid.innerHTML = top7.map(function(app) {
        return `
          <div onclick="openAppDetails('${app.id}')" class="flex flex-col items-center cursor-pointer group">
            <div class="w-full aspect-square rounded-[18px] sm:rounded-[24px] overflow-hidden shrink-0 shadow-md group-hover:scale-105 transition-transform duration-200 bg-white/5">
              <img src="${app.img || ''}" loading="lazy" class="w-full h-full object-cover" alt="${app.name || ''}">
            </div>
            <div class="mt-2 text-center w-full px-1">
              <h3 class="font-bold text-[11px] sm:text-xs md:text-sm text-white truncate group-hover:text-purple-300 transition-colors">${app.name || ''}</h3>
            </div>
          </div>
        `;
      }).join('');
    }

    function renderAllAppsGrid() {
      const grid = document.getElementById('all-apps-grid');
      const endText = document.getElementById('end-feed-text');
      if (!grid) return;
      if (currentSortedApps.length === 0) {
        grid.innerHTML = '<p class="text-xs text-gray-500 col-span-full py-8 text-center">No apps found for this category.</p>';
        if (endText) endText.classList.add('hidden');
        return;
      }
      grid.innerHTML = currentSortedApps.slice(0, displayedCount).map(generateAppCardHTML).join('');
      if (endText) {
        if (displayedCount >= currentSortedApps.length) endText.classList.remove('hidden');
        else endText.classList.add('hidden');
      }
    }

    function handleSortChange(sortType) {
      currentSortedApps = [...storeApps];
      if (sortType === 'alphabetical') {
        currentSortedApps.sort(function(a, b) { return (a.name || '').localeCompare(b.name || ''); });
      } else if (sortType === 'downloads') {
        currentSortedApps.sort(function(a, b) { return (b.downloads || 0) - (a.downloads || 0); });
      } else if (sortType === 'likes') {
        currentSortedApps.sort(function(a, b) { return (b.likes || 0) - (a.likes || 0); });
      } else if (sortType === 'newest') {
        currentSortedApps.sort(function(a, b) { return new Date(b.created_at || 0) - new Date(a.created_at || 0); });
      }
      displayedCount = 10;
      renderAllAppsGrid();
    }

