    function initSlideshowDots() {
      const track = document.getElementById('slideshow-track');
      const dotsContainer = document.getElementById('dots-container');
      if (!track || !dotsContainer) return;
      const cards = track.querySelectorAll('.carousel-card');
      if (cards.length > 0) {
        dotsContainer.innerHTML = Array.from(cards).map(function(_, i) {
          return `
            <button onclick="manualSlideSelect(${i})" class="slide-dot-btn relative h-2 sm:h-2.5 rounded-full bg-white/20 overflow-hidden transition-all duration-300 cursor-pointer ${i === 0 ? 'w-8 sm:w-10 active-dot' : 'w-2 sm:w-2.5'}">
              <div class="progress-fill absolute inset-y-0 left-0 bg-white rounded-full w-0"></div>
            </button>
          `;
        }).join('');
      }
      resetSlideTimer();
    }

    function resetSlideTimer() {
      clearInterval(slideTimer);
      const activeFill = document.querySelector('.slide-dot-btn.active-dot .progress-fill');
      if (activeFill) {
        activeFill.style.transition = 'none';
        activeFill.style.width = '0%';
        setTimeout(function() {
          activeFill.style.transition = `width ${SLIDE_DURATION}ms linear`;
          activeFill.style.width = '100%';
        }, 50);
      }
      slideTimer = setInterval(nextSlide, SLIDE_DURATION);
    }

    function scrollToSlide(index) {
      const track = document.getElementById('slideshow-track');
      if (!track) return;
      const cards = track.querySelectorAll('.carousel-card');
      if (!cards.length) return;
      currentSlideIndex = (index + cards.length) % cards.length;
      track.scrollTo({ left: cards[currentSlideIndex].offsetLeft - track.offsetLeft, behavior: 'smooth' });
      document.querySelectorAll('.slide-dot-btn').forEach(function(dot, idx) {
        const fill = dot.querySelector('.progress-fill');
        if (idx === currentSlideIndex) {
          dot.className = 'slide-dot-btn active-dot relative h-2 sm:h-2.5 rounded-full bg-white/20 overflow-hidden transition-all duration-300 cursor-pointer w-8 sm:w-10';
          if (fill) fill.style.width = '0%';
        } else {
          dot.className = 'slide-dot-btn relative h-2 sm:h-2.5 rounded-full bg-white/20 overflow-hidden transition-all duration-300 cursor-pointer w-2 sm:w-2.5';
          if (fill) fill.style.width = '0%';
        }
      });
    }

    function manualSlideSelect(i) { scrollToSlide(i); resetSlideTimer(); }
    function nextSlide() { scrollToSlide(currentSlideIndex + 1); resetSlideTimer(); }
    function prevSlide() { scrollToSlide(currentSlideIndex - 1); resetSlideTimer(); }

    function calculateAppSearchScore(app, cleanQuery) {
      if (!cleanQuery) return 0;
      let score = 0;
      const name = (app.name || '').toLowerCase();
      const cat = (app.category || '').toLowerCase();
      const desc = (app.description || '').toLowerCase();
      const dev = (app.developer || '').toLowerCase();

      if (name === cleanQuery) score += 100;
      else if (name.startsWith(cleanQuery)) score += 60;
      else if (name.includes(cleanQuery)) score += 40;

      if (cat.includes(cleanQuery)) score += 30;

      const tokens = cleanQuery.split(/\s+/);
      tokens.forEach(token => {
        if (token.length > 1) {
          if (name.includes(token)) score += 15;
          if (cat.includes(token)) score += 10;
          if (dev.includes(token)) score += 8;
          if (desc.includes(token)) score += 5;
        }
      });

      return score;
    }

    function performAdvancedSearch(query) {
      const clean = query.toLowerCase().trim();
      if (!clean) return [];

      const scoredApps = storeApps.map(function(app) {
        return { app: app, score: calculateAppSearchScore(app, clean) };
      }).filter(function(item) { return item.score > 0; });

      scoredApps.sort(function(a, b) { return b.score - a.score; });
      return scoredApps.map(function(item) { return item.app; });
    }

    function onSearchInputChange(value) {
      const desktopClear = document.getElementById('search-clear-btn');
      const mobileClear = document.getElementById('mobile-search-clear-btn');

      if (value.trim().length > 0) {
        if (desktopClear) desktopClear.classList.remove('hidden');
        if (mobileClear) mobileClear.classList.remove('hidden');
        handleSearchSuggestions(value);
      } else {
        if (desktopClear) desktopClear.classList.add('hidden');
        if (mobileClear) mobileClear.classList.add('hidden');
        hideSearchSuggestions();
      }
    }

    function clearSearchInput() {
      const desktopInput = document.getElementById('search-input');
      const mobileInput = document.getElementById('mobile-search-input');
      const desktopClear = document.getElementById('search-clear-btn');
      const mobileClear = document.getElementById('mobile-search-clear-btn');

      if (desktopInput) desktopInput.value = '';
      if (mobileInput) mobileInput.value = '';
      if (desktopClear) desktopClear.classList.add('hidden');
      if (mobileClear) mobileClear.classList.add('hidden');
      hideSearchSuggestions();
    }

    function handleSearchSuggestions(query) {
      const popup = document.getElementById('search-suggestions');
      if (!popup) return;

      const matches = performAdvancedSearch(query).slice(0, 5);

      if (matches.length === 0) {
        popup.classList.add('hidden');
        popup.innerHTML = '';
        return;
      }
      popup.innerHTML = matches.map(function(app) {
        return `
          <div onclick="openAppDetails('${app.id}'); hideSearchSuggestions();" class="flex items-center gap-3 p-2 hover:bg-white/10 rounded-xl cursor-pointer transition-colors">
            <img src="${app.img || ''}" loading="lazy" class="w-8 h-8 rounded-lg object-cover bg-white/5 shrink-0" />
            <div class="min-w-0 flex-1">
              <h4 class="text-xs font-bold text-white truncate">${app.name || ''}</h4>
            </div>
          </div>
        `;
      }).join('');
      popup.classList.remove('hidden');
    }

    function hideSearchSuggestions() {
      const popup = document.getElementById('search-suggestions');
      if (popup) popup.classList.add('hidden');
    }

    function handleSearch(e) {
      if (e) e.preventDefault();
      const desktopInput = document.getElementById('search-input');
      const mobileInput = document.getElementById('mobile-search-input');
      const query = ((desktopInput && desktopInput.value) || (mobileInput && mobileInput.value) || '').toLowerCase().trim();
      if (!query) return;
      executeSearch(query, true);
    }

    function executeSearch(query, updateHash = true) {
      hideSearchSuggestions();
      if (updateHash) window.location.hash = `search/${encodeURIComponent(query)}`;

      const queryDisplay = document.getElementById('search-query-display');
      if (queryDisplay) queryDisplay.innerText = query;

      const grid = document.getElementById('search-results-grid');
      const emptyState = document.getElementById('search-empty-state');
      const loader = document.getElementById('search-loader');

      if (grid) grid.classList.add('hidden');
      if (emptyState) emptyState.classList.add('hidden');
      if (loader) loader.classList.remove('hidden');

      showView('search-page-view');

      setTimeout(function() {
        const results = performAdvancedSearch(query);
        if (loader) loader.classList.add('hidden');

        if (results.length > 0) {
          if (grid) {
            grid.innerHTML = results.map(generateAppCardHTML).join('');
            grid.classList.remove('hidden');
          }
          if (emptyState) emptyState.classList.add('hidden');
        } else {
          if (grid) {
            grid.innerHTML = '';
            grid.classList.add('hidden');
          }
          if (emptyState) emptyState.classList.remove('hidden');
        }
      }, 300);
    }

    async function openAppDetails(appId, updateHash = true) {
      const app = storeApps.find(function(a) { return String(a.id) === String(appId); });
      if (!app) return;
      currentDetailedApp = app;

      if (updateHash) window.location.hash = `app/${app.id}`;

      const detailImg = document.getElementById('detail-app-img');
      if (detailImg) detailImg.src = app.img || '';
      const detailTitle = document.getElementById('detail-app-title');
      if (detailTitle) detailTitle.textContent = app.name || '';
      
      const statDl = document.getElementById('detail-stat-downloads');
      if (statDl) statDl.textContent = app.downloads !== undefined ? Number(app.downloads).toLocaleString() : '—';
      const statSize = document.getElementById('detail-stat-filesize');
      if (statSize) statSize.textContent = app.file_size || '—';
      const statCat = document.getElementById('detail-stat-category');
      if (statCat) statCat.textContent = app.category || '—';
      const statDev = document.getElementById('detail-stat-developer');
      if (statDev) statDev.textContent = app.developer || '—';
      const statSub = document.getElementById('detail-stat-submittedby');
      if (statSub) statSub.textContent = app.submitted_by || '—';

      const descContent = document.getElementById('detail-desc-content');
      const descWrapper = document.getElementById('detail-desc-wrapper');
      const descBtn = document.getElementById('detail-desc-btn');
      if (descContent && descWrapper && descBtn) {
        descContent.innerHTML = app.description || '';
        descWrapper.classList.add('desc-12-lines');
        descBtn.textContent = 'Read more';
        setTimeout(function() {
          if (descContent.scrollHeight > descWrapper.clientHeight) {
            descBtn.classList.remove('hidden');
          } else {
            descBtn.classList.add('hidden');
            descWrapper.classList.remove('desc-12-lines');
          }
        }, 60);
      }

      const tlContainer = document.getElementById('versions-timeline-container');
      if (tlContainer) {
        tlContainer.innerHTML = '<div class="absolute left-2.5 top-3 bottom-3 w-[2px] bg-white/10 pointer-events-none"></div>';
        let versions = [];
        if (supabaseClient) {
          try {
            const res = await supabaseClient.from('app_versions').select('*').eq('app_id', app.id).order('release_date', { ascending: false });
            if (res.data && res.data.length > 0) {

              const seenVersions = new Set();
              versions = res.data.filter(v => {
                const key = v.version_name || v.id;
                if (seenVersions.has(key)) return false;
                seenVersions.add(key);
                return true;
              });
            }
          } catch (e) {}
        }

        if (versions.length > 0) {
          versions.forEach(function(ver, index) {
            const isLatest = index === 0;
            const dot = isLatest ? `<div class="absolute -left-[23px] top-1.5 flex items-center justify-center">
              <span class="animate-ping absolute inline-flex h-3.5 w-3.5 rounded-full bg-white opacity-75"></span>
              <span class="relative inline-flex rounded-full h-2.5 w-2.5 bg-white shadow-[0_0_12px_#ffffff]"></span>
            </div>` : `<div class="absolute -left-[20px] top-1.5 h-2 w-2 rounded-full bg-white/30"></div>`;

            tlContainer.innerHTML += `
              <div class="relative transition-all">
                ${dot}
                <div class="flex items-center justify-between">
                  <button onclick="toggleVersionNotes('ver-${ver.id || index}')" class="font-bold text-base text-white hover:text-purple-300 transition-colors cursor-pointer text-left">
                    ${ver.version_name || ''}
                  </button>
                  <span class="text-xs text-gray-400 font-medium">${ver.release_date ? new Date(ver.release_date).toLocaleDateString(undefined, {month:'short', year:'numeric'}) : ''}</span>
                </div>
                <div id="notes-ver-${ver.id || index}" class="mt-2 text-xs text-gray-300 font-normal leading-relaxed hidden">
                  ${ver.changelog || ''}
                </div>
              </div>
            `;
          });
        } else {
          tlContainer.innerHTML = '';
        }
      }

      const relatedGrid = document.getElementById('related-apps-grid');
      if (relatedGrid) {
        const relatedApps = storeApps.filter(function(x) { return x.category === app.category && String(x.id) !== String(app.id); }).slice(0, 3);
        if (relatedApps.length > 0) {
          relatedGrid.innerHTML = relatedApps.map(generateAppCardHTML).join('');
        } else {
          relatedGrid.innerHTML = '<p class="text-xs text-gray-500 w-full col-span-full">No related apps found.</p>';
        }
      }

      showView('app-details-view');
    }

    async function launchAppPlayer(updateHash = true) {
      if (!currentDetailedApp) return;

      if (updateHash) window.location.hash = `play/${currentDetailedApp.id}`;

      const playerTitle = document.getElementById('player-app-title');
      const playerIframe = document.getElementById('player-iframe');
      const loaderOverlay = document.getElementById('player-loader-overlay');
      const loaderTip = document.getElementById('player-loader-tip');

      if (playerTitle) playerTitle.textContent = currentDetailedApp.name || 'App Player';

      const randomTip = loadingTips[Math.floor(Math.random() * loadingTips.length)];
      if (loaderTip) loaderTip.textContent = randomTip;

      if (loaderOverlay) {
        loaderOverlay.classList.remove('hidden');
        loaderOverlay.classList.remove('opacity-0', 'pointer-events-none');
      }

      if (playerIframe) {
        playerIframe.removeAttribute('src');
        playerIframe.removeAttribute('srcdoc');

        if (currentDetailedApp.html_code) {
          playerIframe.srcdoc = currentDetailedApp.html_code;
        } else if (currentDetailedApp.app_url) {
          try {
            const response = await fetch(currentDetailedApp.app_url);
            if (!response.ok) throw new Error('CORS or fetch error');
            const extractedHtml = await response.text();
            playerIframe.srcdoc = extractedHtml;
          } catch (err) {
            console.warn('HTML Extractor fallback to src URL:', err);
            playerIframe.src = currentDetailedApp.app_url;
          }
        } else {
          playerIframe.srcdoc = `<html><body style="background:#000;color:#fff;display:flex;align-items:center;justify-content:center;height:100vh;font-family:sans-serif;"><h3>No executable HTML code found for this app.</h3>
<style id="game-card-redesign">
  /* UBGForever storefront-style game cards */
  #game-vault-view #sections-container{display:block!important;margin-top:30px!important;}
  #game-vault-view .safe-game-section{border:0!important;background:transparent!important;box-shadow:none!important;padding:0!important;backdrop-filter:none!important;}
  #game-vault-view .letter-header{padding:0 2px 16px!important;margin:0!important;font-size:13px!important;letter-spacing:.12em!important;}
  #game-vault-view .safe-game-cards{display:grid!important;grid-template-columns:repeat(5,minmax(0,1fr))!important;gap:16px!important;align-items:stretch!important;}
  #game-vault-view .safe-game-card{position:relative!important;display:flex!important;flex-direction:column!important;align-items:stretch!important;justify-content:flex-start!important;gap:0!important;min-width:0!important;min-height:0!important;height:100%!important;padding:0!important;overflow:hidden!important;border:1px solid rgba(255,255,255,.09)!important;border-radius:20px!important;background:linear-gradient(180deg,rgba(255,255,255,.075),rgba(255,255,255,.035))!important;color:#fff!important;text-align:left!important;box-shadow:0 12px 30px rgba(0,0,0,.18)!important;transition:transform .2s ease,border-color .2s ease,box-shadow .2s ease,background .2s ease!important;}
  #game-vault-view .safe-game-card:hover{transform:translateY(-5px)!important;border-color:rgba(129,140,248,.5)!important;background:linear-gradient(180deg,rgba(99,102,241,.17),rgba(255,255,255,.045))!important;box-shadow:0 20px 45px rgba(0,0,0,.32),0 0 0 1px rgba(129,140,248,.08)!important;}
  #game-vault-view .safe-game-art{height:122px!important;display:flex!important;align-items:center!important;justify-content:center!important;position:relative!important;overflow:hidden!important;background:radial-gradient(circle at 50% 35%,rgba(99,102,241,.32),transparent 58%),linear-gradient(135deg,rgba(59,130,246,.20),rgba(124,58,237,.20))!important;border-bottom:1px solid rgba(255,255,255,.08)!important;}
  #game-vault-view .safe-game-art:before{content:"";position:absolute;inset:0;background:linear-gradient(135deg,rgba(255,255,255,.08),transparent 45%,rgba(0,0,0,.16));pointer-events:none;}
  #game-vault-view .safe-game-icon{position:relative!important;z-index:1!important;width:58px!important;height:58px!important;display:flex!important;align-items:center!important;justify-content:center!important;border-radius:17px!important;background:rgba(8,10,25,.72)!important;border:1px solid rgba(255,255,255,.16)!important;font-size:29px!important;box-shadow:0 10px 28px rgba(0,0,0,.28)!important;}
  #game-vault-view .safe-game-play{position:absolute!important;right:10px!important;top:10px!important;padding:5px 8px!important;border-radius:8px!important;background:rgba(7,8,18,.62)!important;border:1px solid rgba(255,255,255,.12)!important;color:#c7d2fe!important;font-size:9px!important;font-weight:900!important;letter-spacing:.1em!important;}
  #game-vault-view .safe-game-info{display:flex!important;flex-direction:column!important;gap:5px!important;min-width:0!important;padding:14px 14px 16px!important;flex:1!important;}
  #game-vault-view .safe-game-name{display:block!important;min-height:40px!important;font-size:14px!important;line-height:1.35!important;font-weight:850!important;color:#f4f4f5!important;overflow:hidden!important;}
  #game-vault-view .safe-game-type{font-size:10px!important;color:#71717a!important;font-weight:700!important;letter-spacing:.04em!important;text-transform:uppercase!important;}
  #game-vault-view .safe-game-arrow{position:absolute!important;right:13px!important;bottom:13px!important;width:27px!important;height:27px!important;display:flex!important;align-items:center!important;justify-content:center!important;border-radius:9px!important;background:rgba(255,255,255,.06)!important;color:#a5b4fc!important;font-size:15px!important;transition:.2s!important;}
  #game-vault-view .safe-game-card:hover .safe-game-arrow{background:rgba(129,140,248,.2)!important;color:#fff!important;transform:translateX(2px)!important;}
  #game-vault-view .safe-game-empty{grid-column:1/-1!important;border:1px dashed rgba(255,255,255,.12)!important;border-radius:18px!important;padding:44px!important;background:rgba(255,255,255,.025)!important;}
  @media(max-width:1200px){#game-vault-view .safe-game-cards{grid-template-columns:repeat(4,minmax(0,1fr))!important;}}
  @media(max-width:900px){#game-vault-view .safe-game-cards{grid-template-columns:repeat(3,minmax(0,1fr))!important;}}
  @media(max-width:650px){#game-vault-view .safe-game-cards{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:12px!important;}#game-vault-view .safe-game-art{height:105px!important;}#game-vault-view .safe-game-info{padding:11px!important;}}
  @media(max-width:390px){#game-vault-view .safe-game-cards{grid-template-columns:1fr!important;}}
</style>


</body></html>`;
        }
      }

      showView('app-player-view');

      const fakeDelay = Math.floor(Math.random() * 800) + 1200;
      setTimeout(function() {
        if (loaderOverlay) {
          loaderOverlay.classList.add('opacity-0', 'pointer-events-none');
          setTimeout(function() { loaderOverlay.classList.add('hidden'); }, 300);
        }
      }, fakeDelay);
    }

    function closeAppPlayer() {
      const playerIframe = document.getElementById('player-iframe');

      if (settingsState.ramOpt && playerIframe) {
        playerIframe.src = 'about:blank';
        playerIframe.removeAttribute('srcdoc');
      }

      if (document.fullscreenElement) {
        document.exitFullscreen().catch(function() {});
      }
      if (currentDetailedApp) {
        window.location.hash = `app/${currentDetailedApp.id}`;
        showView('app-details-view');
      } else {
        window.location.hash = 'home';
        showView('home-page-view');
      }
    }

    function openInNewTab() {
      if (!currentDetailedApp || !currentDetailedApp.app_url) return;
      window.open(currentDetailedApp.app_url, '_blank');
    }

    function downloadCurrentApp() {
      if (!currentDetailedApp) return;
      const downloadTarget = currentDetailedApp.download_url || currentDetailedApp.app_url;
      if (!downloadTarget) return;
      const a = document.createElement('a');
      a.href = downloadTarget;
      a.download = currentDetailedApp.name || 'download';
      a.target = '_blank';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
    }

    function togglePlayerFullscreen() {
      const frameContainer = document.getElementById('player-frame-container');
      const targetElement = frameContainer || document.getElementById('app-player-view');
      if (!targetElement) return;

      if (!document.fullscreenElement) {
        targetElement.requestFullscreen().catch(function(err) { console.error(err); });
      } else {
        document.exitFullscreen().catch(function(err) { console.error(err); });
      }
    }

    function toggleDescription() {
      const descWrapper = document.getElementById('detail-desc-wrapper');
      const descBtn = document.getElementById('detail-desc-btn');
      if (descWrapper && descBtn) {
        if (descWrapper.classList.contains('desc-12-lines')) {
          descWrapper.classList.remove('desc-12-lines');
          descBtn.textContent = 'Read less';
        } else {
          descWrapper.classList.add('desc-12-lines');
          descBtn.textContent = 'Read more';
        }
      }
    }

    function toggleVersionNotes(verKey) {
      const notes = document.getElementById(`notes-${verKey}`);
      if (notes) notes.classList.toggle('hidden');
    }

    let isMobileSearchOpen = false;
    function toggleMobileSearch() {
      const categoryBar = document.getElementById('mobile-category-bar');
      const searchWrapper = document.getElementById('mobile-search-wrapper');
      const searchIcon = document.getElementById('mobile-search-icon');
      const searchInput = document.getElementById('mobile-search-input');

      isMobileSearchOpen = !isMobileSearchOpen;

      if (isMobileSearchOpen) {
        categoryBar.classList.add('max-w-0', 'opacity-0', 'pointer-events-none');
        searchWrapper.classList.remove('mobile-search-closed');
        searchWrapper.classList.add('mobile-search-open');
        if (searchIcon) searchIcon.style.transform = 'rotate(90deg)';
        setTimeout(function() { if (searchInput) searchInput.focus(); }, 150);
      } else {
        categoryBar.classList.remove('max-w-0', 'opacity-0', 'pointer-events-none');
        searchWrapper.classList.remove('mobile-search-open');
        searchWrapper.classList.add('mobile-search-closed');
        if (searchIcon) searchIcon.style.transform = 'rotate(0deg)';
      }
    }

    window.addEventListener('hashchange', handleHashRouter);

    if (document.readyState === 'complete' || document.readyState === 'interactive') {
      initApp().finally(function() { setTimeout(dismissLoader, 1450); });
    } else {
      document.addEventListener('DOMContentLoaded', function() {
        initApp().finally(function() { setTimeout(dismissLoader, 1450); });
      });
    }
    setTimeout(dismissLoader, 3000);
  

/* ===== extracted inline script ===== */

(function(){
  window.eduSearch=function(){
    var input=document.getElementById('edu-search-input');
    if(!input)return;
    var q=input.value.trim();
    if(q){window.open('https://www.google.com/search?q='+encodeURIComponent(q),'_blank','noopener');}
  };
  var input=document.getElementById('edu-search-input');
  if(input){input.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();window.eduSearch();}});}
})();


/* ===== extracted inline script ===== */

(function(){
  window.enterUBGMain=function(){
    document.body.classList.remove('ubg-landing-mode');
    var landing=document.getElementById('ubg-landing-page');
    if(landing){landing.style.opacity='0';landing.style.pointerEvents='none';setTimeout(function(){landing.remove();},220);}
    var overlay=document.getElementById('startup-overlay');
    if(overlay){overlay.remove();}
    document.body.style.overflow='';
    window.scrollTo({top:0,behavior:'instant'});
  };
})();
